<?php
require __DIR__.'/test_support.php';['db'=>$db,'fixture'=>$f]=erpTestFixture();
require __DIR__.'/learning_sharing_fixture.php';$f=learningSharingFixture($db,$f);
require __DIR__.'/../includes/exam_paper_service.php';
$super=learningActor($db,$f['ids']['super_admin']);$teacher=learningActor($db,$f['ids']['teacher']);
$scope=learningCatalogScope($db,1,$f['class'],$f['subject'])['shared'];$class=$scope['class_id'];$subject=$scope['subject_id'];
$chapter=curriculumEnsureChapter($db,0,$class,$subject,'Deletion chapter');$topic=curriculumEnsureTopic($db,0,$chapter,'Deletion topic');
$common=['class_id'=>$class,'subject_id'=>$subject,'chapter'=>'Deletion chapter','topic_id'=>$topic,'visibility'=>'public','difficulty'=>'Easy','required_minutes'=>2,'cognitive_domain'=>'Knowledge'];
$q=learningSaveQuestion($db,$super,$common+['type'=>'Short','marks'=>2,'question_text'=>'Protected shared body'],null,'learning');
$mcq=learningSaveQuestion($db,$super,$common+['type'=>'MCQ','marks'=>1,'question_text'=>'Protected exam body','option_a'=>'a','option_b'=>'b','option_c'=>'c','option_d'=>'d','correct_option'=>'A'],null,'exam');
$note=learningSaveNote($db,$super,$common+['title'=>'Protected note','content'=>'<p>Keep my content</p>','topic'=>'Deletion topic']);
$config=['full_marks'=>1,'duration_minutes'=>10,'rows'=>[['name'=>'MCQ','type'=>'MCQ','chapter_ids'=>[$chapter],'topic_ids'=>[$topic],'count'=>1,'total_marks'=>1]]];
$grid=examSaveGrid($db,$super,$class,$subject,'Protected grid',$config);
$local=learningSaveQuestion($db,$teacher,['class_id'=>$f['class'],'subject_id'=>$f['subject'],'chapter'=>'Deletion chapter','catalog_topic_id'=>$topic,'type'=>'Short','marks'=>2,'question_text'=>'Private school question body'],null);
$report=curriculumDependencyReport($db,0,'chapters',$chapter);
erpEqual($report['total'],5,'All active bank, exam, note, grid and cross-school references count');
erpEqual(count($report['groups']),4,'Dependencies are grouped by section');
erpCheck(!str_contains(json_encode($report),'Private school question body'),'Dependency metadata does not expose private bodies');
$schoolItems=[];foreach($report['groups'] as $g)foreach($g['items'] as $i)if($i['school']!=='Shared catalog')$schoolItems[]=$i;
erpEqual($schoolItems[0]['url'],null,'Cross-school dependency has no unauthorized content link');
erpReject(fn()=>curriculumDelete($db,0,'chapters',$chapter),'Active chapter deletion blocked');
erpReject(fn()=>curriculumDelete($db,0,'topics',$topic),'Active topic deletion blocked');
learningSetArchived($db,$super,'questions',$q,true);learningSetArchived($db,$super,'questions',$mcq,true,'exam');learningSetArchived($db,$super,'learning_notes',$note,true);learningSetArchived($db,$teacher,'questions',$local,true);
erpEqual(curriculumDependencyReport($db,0,'chapters',$chapter)['total'],1,'Archived content no longer blocks, active grid still does');
examArchiveGrid($db,$super,$grid,true);
$old=$db->query('SELECT id,question_text,answer,topic_id,catalog_topic_id FROM questions ORDER BY id')->fetchAll();
curriculumDelete($db,0,'chapters',$chapter);
erpCheck((bool)schoolRecord($db,'chapters',$chapter,0)['archived_at'],'Chapter is recoverably deleted');
erpCheck((bool)schoolRecord($db,'topics',$topic,0)['archived_at'],'Empty topics are removed with parent');
erpEqual($db->query('SELECT id,question_text,answer,topic_id,catalog_topic_id FROM questions ORDER BY id')->fetchAll(),$old,'Deleting catalog never erases or detaches saved content');
erpCheck(!in_array($chapter,array_column(learningCatalogChapters($db,$super,$class,$subject),'id')),'Deleted chapters absent from active selectors');
erpReject(fn()=>learningCatalogTopics($db,$super,$class,$subject,$chapter),'Deleted chapter cannot provide topic options');
erpReject(fn()=>learningSetArchived($db,$super,'questions',$q,false),'Restore catalog before question');
erpReject(fn()=>learningSetArchived($db,$super,'learning_notes',$note,false),'Restore catalog before note');
erpReject(fn()=>examArchiveGrid($db,$super,$grid,false),'Restore catalog before exam grid');
erpReject(fn()=>curriculumRestore($db,0,'topics',$topic),'Restore chapter before topic');
erpReject(fn()=>curriculumEnsureChapter($db,0,$class,$subject,'Deletion chapter'),'Cannot recreate a deleted chapter under a new ID');
curriculumRestore($db,0,'chapters',$chapter);
erpEqual(schoolRecord($db,'topics',$topic,0)['archived_at'],null,'Parent restore brings back cascaded empty topic');
learningSetArchived($db,$super,'questions',$q,false);examArchiveGrid($db,$super,$grid,false);
erpEqual((int)learningContentRecord($db,$super,'questions',$q,'bank')['id'],$q,'Same content ID can be recovered after parent restore');
// Same-name legacy aliases cannot bypass a dependency check.
$alias=insertRecord($db,'chapters',['school_id'=>0,'class_id'=>$class,'subject_id'=>$subject,'name'=>'DELETION CHAPTER']);
$ta=insertRecord($db,'topics',['school_id'=>0,'class_id'=>$class,'subject_id'=>$subject,'chapter_id'=>$alias,'name'=>'DELETION TOPIC']);
$db->prepare('UPDATE questions SET topic_id=?,catalog_topic_id=? WHERE id=?')->execute([$ta,$ta,$q]);
erpCheck(curriculumDependencyReport($db,0,'topics',$topic)['total']>=1,'Historical duplicate topic references are recognized');
erpReject(fn()=>curriculumDelete($db,0,'topics',$topic),'Cannot delete visible representative while an alias is in use');
// Only empty children removed in this parent operation are restored with it.
$empty=curriculumEnsureChapter($db,0,$class,$subject,'Empty removable chapter');$manual=curriculumEnsureTopic($db,0,$empty,'Already removed');$child=curriculumEnsureTopic($db,0,$empty,'Empty child');
curriculumDelete($db,0,'topics',$manual);curriculumDelete($db,0,'chapters',$empty);curriculumRestore($db,0,'chapters',$empty);
erpCheck((bool)schoolRecord($db,'topics',$manual,0)['archived_at'],'Previously deleted child stays deleted');
erpEqual(schoolRecord($db,'topics',$child,0)['archived_at'],null,'Only cascaded child is automatically restored');
curriculumRestore($db,0,'topics',$manual);
erpReject(fn()=>curriculumDelete($db,1,'chapters',$chapter),'Wrong school cannot remove catalog entry');
// Unknown-class legacy notes still protect matching label-based curriculum.
$legacy=insertRecord($db,'learning_notes',['school_id'=>0,'class_level'=>schoolRecord($db,'classes',$class,0)['name'],'subject_name'=>schoolRecord($db,'subjects',$subject,0)['name_en'],'chapter'=>'Empty removable chapter','topic'=>'Empty child','title'=>'Legacy note','content'=>'Preserve legacy body','visibility'=>'public']);
erpEqual(curriculumDependencyReport($db,0,'topics',$child)['total'],1,'Legacy note labels protect topics without IDs');
erpReject(fn()=>curriculumDelete($db,0,'topics',$child),'Legacy note blocks topic removal');
$db->prepare('UPDATE learning_notes SET archived_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$legacy]);curriculumDelete($db,0,'topics',$child);
erpReject(fn()=>curriculumAssertContentRestorable($db,schoolRecord($db,'learning_notes',$legacy,0)),'Legacy topic must be restored before legacy note');
erpEqual((int)$db->query("SELECT meta_value FROM app_meta WHERE meta_key='workflow_schema'")->fetchColumn(),18,'Schema18 retains catalog deletion fields');
echo 'Curriculum deletion checks passed: '.$GLOBALS['erp_checks'].PHP_EOL;
